289			"unknown top-level field repeats": `{"note":1,"note":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
290			"unknown graph field repeats":     doc(`{"meta":"x","meta":"y","datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
291			"unknown record field repeats":    doc(`{"datasets":[{"name":"A","note":"x","note":"y","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
292			"duplicate names inside upstreams array": doc(
293				`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A","A"]}]}`),
294		}
295		for name, data := range cases {
296			t.Run(name, func(t *testing.T) {
297				parsed, err := ParseSnapshot([]byte(data))
298				if err != nil {
299					t.Fatalf("ParseSnapshot rejected a legal document: %v", err)
300				}
301				if parsed.ContentID != id {
302					t.Errorf("content id = %s, want %s", parsed.ContentID, id)
303				}
304			})
305		}
306	}
