308	// TestParseSnapshotCaseVariantSpellings: a field written once in any letter
309	// casing the reader already supports keeps working; only declaring it twice
310	// is an error.
311	func TestParseSnapshotCaseVariantSpellings(t *testing.T) {
312		id := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`).ContentID
313		data := `{"FORMATVERSION":1,"ContentID":"` + id + `","GRAPH":{"Datasets":` +
314			`[{"Name":"A","Upstreams":[]},{"NAME":"B","UPSTREAMS":["A"]}]}}`
315		parsed, err := ParseSnapshot([]byte(data))
316		if err != nil {
317			t.Fatalf("case-variant spellings rejected: %v", err)
318		}
319		if parsed.ContentID != id {
320			t.Errorf("content id = %s, want %s", parsed.ContentID, id)
321		}
322	}
