324	// TestParseSnapshotRejectsUnicodeFoldDuplicates: two keys that the JSON
325	// reader resolves to the same struct field through Unicode simple case
326	// folding — not merely ASCII case — make the snapshot ambiguous. U+017F
327	// LATIN SMALL LETTER LONG S ("ſ") is a fold equivalent of "s", so
328	// "formatVerſion" and "formatVersion" select the same field, as do
329	// "dataſets"/"datasets" and "upſtreams"/"upstreams". Writing the rune
330	// directly or via a JSON escape must not matter, and identical values, a null
331	// first value, or reversed declaration order must not save the document. The
332	// error names the canonical field and, inside a datasets record, its index.
333	func TestParseSnapshotRejectsUnicodeFoldDuplicates(t *testing.T) {
334		const (
335			longS = "ſ" // U+017F LATIN SMALL LETTER LONG S, folds to ASCII "s"
336			// longSEscape is the JSON escape spelling of the same rune as literal
337			// document bytes (backslash, u, 0, 1, 7, f).
338			longSEscape = "\\" + "u017f"
339		)
340		graph := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`
341		id := snapshotOf(t, graph).ContentID
342		doc := func(body string) string {
343			return `{"formatVersion":1,"contentId":"` + id + `","graph":` + body + `}`
344		}
345	
346		cases := map[string]struct {
347			data  string
348			field string
349		}{
350			"long s version 2 then 1": {
351				`{"formatVer` + longS + `ion":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
352				"formatVersion",
353			},
354			"long s version reversed order": {
355				`{"formatVersion":1,"formatVer` + longS + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`,
356				"formatVersion",
357			},
358			"long s version identical values": {
359				`{"formatVer` + longS + `ion":1,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
360				"formatVersion",
361			},
362			"long s version via JSON escape": {
363				`{"formatVer` + longSEscape + `ion":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
364				"formatVersion",
365			},
366			"null long s version then valid": {
367				`{"formatVer` + longS + `ion":null,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
368				"formatVersion",
369			},
370			"datasets versus long s datasets": {
371				doc(`{"data` + longS + `ets":[],"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
372				"datasets",
373			},
374			"long s datasets via JSON escape": {
375				doc(`{"data` + longSEscape + `ets":[],"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
376				"datasets",
377			},
378			"upstreams versus long s upstreams": {
379				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longS + `treams":["A"],"upstreams":["A"]}]}`),
380				"upstreams",
381			},
382			"long s upstreams via JSON escape": {
383				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longSEscape + `treams":["A"],"upstreams":["A"]}]}`),
384				"upstreams",
385			},
386			"null long s upstreams then valid": {
387				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longS + `treams":null,"upstreams":["A"]}]}`),
388				"upstreams",
389			},
390		}
391		for name, tc := range cases {
392			t.Run(name, func(t *testing.T) {
393				// Every "escape" case really must carry ASCII escape bytes.
394				if strings.Contains(name, "escape") && !strings.Contains(tc.data, longSEscape) {
395					t.Fatalf("test case %q does not actually use a JSON escape", name)
396				}
397				_, err := ParseSnapshot([]byte(tc.data))
398				if !errors.Is(err, ErrInvalidArgument) {
399					t.Fatalf("err = %v, want ErrInvalidArgument", err)
400				}
401				if !strings.Contains(err.Error(), `"`+tc.field+`"`) {
402					t.Errorf("err = %q, want it to name canonical field %q", err, tc.field)
403				}
404			})
405		}
406	
407		// The duplicate lives in the second dataset record; the error must locate
408		// that record by its datasets array index even for a Unicode-fold key.
409		indexed := doc(`{"datasets":[{"name":"A","upstreams":[]},{"up` + longS + `treams":["A"],"name":"B","upstreams":["A"]}]}`)
410		if _, err := ParseSnapshot([]byte(indexed)); err == nil || !strings.Contains(err.Error(), "index 1") {
411			t.Errorf("err = %v, want the datasets index of the offending record", err)
412		}
413	
414		// A top-level long-s spelling twice also collides at the top level.
415		twice := `{"formatVer` + longS + `ion":1,"formatVer` + longS + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`
416		if _, err := ParseSnapshot([]byte(twice)); err == nil ||
417			!strings.Contains(err.Error(), `"formatVersion"`) ||
418			!strings.Contains(err.Error(), "top level") {
419			t.Errorf("err = %v, want a top-level formatVersion duplicate error", err)
420		}
421	}
422	
423	// TestParseSnapshotUnicodeFoldSpellingDeclaredOnce preserves read
424	// compatibility: a known field written exactly once in a Unicode-fold
425	// spelling is still recognized, and a key with the same name nested inside an
426	// unknown field is independent of the outer object's known-field check.
427	func TestParseSnapshotUnicodeFoldSpellingDeclaredOnce(t *testing.T) {
428		const (
429			longS       = "ſ"
430			longSEscape = "\\" + "u017f"
431		)
432		graph := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`
433		id := snapshotOf(t, graph).ContentID
434	
435		cases := map[string]string{
436			"long s version declared once": `{"formatVer` + longS + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`,
437			"long s datasets declared once": `{"formatVersion":1,"contentId":"` + id +
438				`","graph":{"data` + longS + `ets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}}`,
439			"long s upstreams declared once": `{"formatVersion":1,"contentId":"` + id +
440				`","graph":{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longS + `treams":["A"]}]}}`,
441			"escaped long s version declared once": `{"formatVer` + longSEscape + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`,
442			"same key nested inside unknown field": `{"formatVersion":1,"contentId":"` + id + `","graph":` + graph +
443				`,"meta":{"formatVersion":2,"datasets":null}}`,
444			"fold-spelled key nested inside unknown field": `{"formatVersion":1,"contentId":"` + id + `","graph":` +
445				graph + `,"meta":{"formatVer` + longS + `ion":2,"data` + longS + `ets":[]}}`,
446		}
447		for name, data := range cases {
448			t.Run(name, func(t *testing.T) {
449				parsed, err := ParseSnapshot([]byte(data))
450				if err != nil {
451					t.Fatalf("a field declared once in a fold spelling was rejected: %v", err)
452				}
453				if parsed.ContentID != id {
454					t.Errorf("content id = %s, want %s", parsed.ContentID, id)
455				}
456			})
457		}
458	}
459	
460	// A is a root source of B, C depends on B; repointing B at another root X must
461	// report BOTH B and C changing source from A to X.
462	func TestCompareHeadlineRootSourceChange(t *testing.T) {
463		oldSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"C","upstreams":["B"]}]}`)
464		newSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"X","upstreams":[]},{"name":"B","upstreams":["X"]},{"name":"C","upstreams":["B"]}]}`)
465	
466		report := CompareSnapshots(oldSnap, newSnap)
467		if got, want := report.NewDatasets, []string{"X"}; !reflect.DeepEqual(got, want) {
468			t.Errorf("NewDatasets = %v, want %v", got, want)
469		}
470		if len(report.RemovedDatasets) != 0 {
471			t.Errorf("RemovedDatasets = %v, want empty", report.RemovedDatasets)
472		}
473		if got, want := report.ChangedDatasets, []string{"B"}; !reflect.DeepEqual(got, want) {
474			t.Errorf("ChangedDatasets = %v, want %v", got, want)
475		}
476		wantAdded := []Relation{{Upstream: "X", Downstream: "B"}}
477		wantRemoved := []Relation{{Upstream: "A", Downstream: "B"}}
478		if !reflect.DeepEqual(report.AddedRelations, wantAdded) {
479			t.Errorf("AddedRelations = %v, want %v", report.AddedRelations, wantAdded)
480		}
481		if !reflect.DeepEqual(report.RemovedRelations, wantRemoved) {
482			t.Errorf("RemovedRelations = %v, want %v", report.RemovedRelations, wantRemoved)
483		}
484		wantRootChanges := []RootSourceChange{
485			{Dataset: "B", OldRoots: []string{"A"}, NewRoots: []string{"X"}},
486			{Dataset: "C", OldRoots: []string{"A"}, NewRoots: []string{"X"}},
487		}
488		if !reflect.DeepEqual(report.RootSourceChanges, wantRootChanges) {
489			t.Errorf("RootSourceChanges = %v\nwant %v", report.RootSourceChanges, wantRootChanges)
490		}
491	}
