493	// TestCompareNodeDeletionCascadesRelations verifies that removing a node lists
494	// every edge incident to it among the removed relations.
495	func TestCompareNodeDeletionCascadesRelations(t *testing.T) {
496		oldSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"C","upstreams":["B"]}]}`)
