366		graphPath := writeFile(t, "g.json", abcGraph)
367		var wg sync.WaitGroup
368		codes := make(chan int, n)
369		for i := 0; i < n; i++ {
370			wg.Add(1)
371			go func() {
372				defer wg.Done()
373				codes <- run([]string{"snapshot", graphPath, target})
374			}()
375		}
376		wg.Wait()
377		close(codes)
378		for code := range codes {
379			if code != 0 {
380				t.Errorf("concurrent same-content save exit = %d, want 0", code)
381			}
382		}
383		if _, err := chainledger.ParseSnapshot([]byte(readFile(t, target))); err != nil {
384			t.Errorf("target invalid after concurrent saves: %v", err)
385		}
