469		dupPath, dupContent := dupFieldSnapshot(t, abcGraph)
470		if err := os.WriteFile(dupPath, []byte(dupContent), 0o644); err != nil {
471			t.Fatalf("write dup: %v", err)
472		}
473	
474		stdout, stderr, exit := captureStdout(t, func() int {
475			return run([]string{"trace", dupPath, "C"})
476		})
477		if exit == 0 {
478			t.Fatalf("trace succeeded on an ambiguous snapshot")
479		}
480		if stdout != "" {
481			t.Errorf("stdout = %q, want empty on rejection", stdout)
482		}
483		if !strings.Contains(stderr, dupPath) || !strings.Contains(stderr, "formatVersion") {
484			t.Errorf("stderr = %q, must name the file and the duplicated field", stderr)
485		}
