494	// TestCLISnapshotRefusesDuplicateFieldTarget: an existing target whose graph
495	// only resolves because a repeated field was silently collapsed counts as
496	// corrupt — the save is refused even when the resolved graph equals the
497	// current content, and the target keeps every byte and its mtime.
498	func TestCLISnapshotRefusesDuplicateFieldTarget(t *testing.T) {
499		dir := t.TempDir()
500		target := filepath.Join(dir, "snap.json")
501	
502		// Seed a valid snapshot of the same content, then inject a duplicate
503		// graph field: an empty graph first, the real graph second. The resolved
504		// graph still matches the current content exactly.
505		if _, stderr, exit := snapshotViaCLI(t, abcGraph, target); exit != 0 {
506			t.Fatalf("seed snapshot: %s", stderr)
507		}
508		valid := readFile(t, target)
509		dup := strings.Replace(valid, `"graph": {`, `"graph": {"datasets": []}, "graph": {`, 1)
510		if dup == valid {
511			t.Fatalf("could not inject duplicate graph into %s", valid)
512		}
513		if err := os.WriteFile(target, []byte(dup), 0o644); err != nil {
514			t.Fatalf("write dup: %v", err)
515		}
516		infoBefore, err := os.Stat(target)
517		if err != nil {
518			t.Fatalf("stat: %v", err)
519		}
520	
521		graphPath := writeFile(t, "graph.json", abcGraph)
522		stdout, stderr, exit := captureStdout(t, func() int {
523			return run([]string{"snapshot", graphPath, target})
524		})
525		if exit == 0 {
526			t.Fatalf("snapshot over a duplicate-field target succeeded")
527		}
528		if !strings.Contains(stderr, "refusing to overwrite") || !strings.Contains(stderr, target) {
529			t.Errorf("stderr = %q, want refusal naming the target", stderr)
530		}
531		if stdout != "" {
532			t.Errorf("stdout = %q, want no content id on refusal", stdout)
533		}
534		if got := readFile(t, target); got != dup {
535			t.Errorf("target changed after refusal:\n got %s\nwant %s", got, dup)
536		}
537		infoAfter, _ := os.Stat(target)
538		if !infoAfter.ModTime().Equal(infoBefore.ModTime()) {
539			t.Errorf("refusal rewrote the target: mtime %s -> %s", infoBefore.ModTime(), infoAfter.ModTime())
540		}
541	}
542	
543	const (
544		// longS is U+017F LATIN SMALL LETTER LONG S, a Unicode simple case fold
545		// of ASCII "s": the JSON reader maps "formatVerſion" to formatVersion.
546		longS = "ſ"
547		// longSEscape spells the same rune as literal JSON escape bytes.
548		longSEscape = "\\" + "u017f"
549	)
550	
551	// unicodeDupFieldSnapshot seeds a valid snapshot of graphJSON, then returns
552	// its path together with bytes that declare formatVersion twice — first 2
553	// under a long-s fold spelling, then the valid 1 under the canonical spelling.
554	// The surviving value still describes the same content, so only the
555	// duplicate-field rule stands between the file and acceptance. The caller
556	// writes the returned content to the path itself; spelling is either longS
557	// (rune written directly) or longSEscape (JSON escape).
558	func unicodeDupFieldSnapshot(t *testing.T, graphJSON, spelling string) (path, content string) {
559		t.Helper()
560		target := filepath.Join(t.TempDir(), "snap.json")
561		if _, stderr, exit := snapshotViaCLI(t, graphJSON, target); exit != 0 {
562			t.Fatalf("seed snapshot: %s", stderr)
563		}
564		valid := readFile(t, target)
565		if err := os.Remove(target + ".lock"); err != nil {
566			t.Fatalf("remove seed lock: %v", err)
567		}
568		dup := strings.Replace(valid, `"formatVersion": 1`,
569			`"formatVer`+spelling+`ion": 2, "formatVersion": 1`, 1)
570		if dup == valid {
571			t.Fatalf("could not inject a long-s duplicate field into %s", valid)
572		}
573		return target, dup
574	}
575	
576	func TestCLICompareRejectsUnicodeFoldDuplicates(t *testing.T) {
577		for _, tc := range []struct {
578			name     string
579			spelling string
580		}{
581			{"rune written directly", longS},
582			{"JSON escape spelling", longSEscape},
583		} {
584			t.Run(tc.name, func(t *testing.T) {
