593				}
594	
595				for _, side := range []struct {
596					name string
597					args []string
598					want string
599				}{
600					{"duplicate in old snapshot", []string{"compare", dupPath, good}, "old snapshot"},
601					{"duplicate in new snapshot", []string{"compare", good, dupPath}, "new snapshot"},
602				} {
603					t.Run(side.name, func(t *testing.T) {
604						stdout, stderr, exit := captureStdout(t, func() int { return run(side.args) })
605						if exit == 0 {
606							t.Fatalf("%v succeeded, want failure", side.args)
607						}
608						if stdout != "" {
609							t.Errorf("stdout = %q, want empty on rejection", stdout)
610						}
611						if !strings.Contains(stderr, side.want) || !strings.Contains(stderr, dupPath) {
612							t.Errorf("stderr = %q, must name the %s file", stderr, side.want)
613						}
614						if !strings.Contains(stderr, "formatVersion") {
615							t.Errorf("stderr = %q, must name the duplicated field", stderr)
616						}
617						if got := readFile(t, dupPath); got != dupContent {
618							t.Errorf("compare modified the snapshot:\n%s", got)
619						}
620						if _, err := os.Stat(dupPath + ".lock"); !os.IsNotExist(err) {
621							t.Errorf("compare created a lock file: %v", err)
622						}
623					})
624				}
625			})
626		}
627	}
628	
629	func TestCLITraceRejectsUnicodeFoldDuplicates(t *testing.T) {
630		dupPath, dupContent := unicodeDupFieldSnapshot(t, abcGraph, longS)
631		if err := os.WriteFile(dupPath, []byte(dupContent), 0o644); err != nil {
632			t.Fatalf("write dup: %v", err)
633		}
